// Static catalog for the UI capture fixture home.
//
// Everything here is plain data: the generator (generate.mjs) turns it into
// provider-format JSONL with a seeded PRNG, so the same catalog always yields
// byte-identical files. Edit this file to change what the captures show; bump
// FIXTURE_VERSION whenever the generated bytes change on purpose.

/** Bumped on any intentional change to the generated bytes. */
export const FIXTURE_VERSION = 3;

/**
 * Wall clock the browser is frozen at during captures (09:00 KST). Every
 * fixture timestamp lies before it, so relative labels ("2 hours ago") are
 * stable. It also lies more than 30 days in the past of any real capture
 * date, so the server-side archive expiry check (which uses the real clock)
 * always sees every fixture session as expired - a stable set.
 */
export const FIXED_NOW_ISO = "2026-06-30T00:00:00.000Z";

/** Seed for the deterministic PRNG. */
export const SEED = 0x5eed_0c4f;

/** Exact viewer-visible message count of the large transcript session. */
export const LARGE_SESSION_MESSAGES = 1369;

const HOUR = 60 * 60 * 1000;

